SELECT CASE WHEN balance >= 78000 THEN 'high' WHEN balance >= 35000 THEN 'mid' ELSE 'low' END AS balance_bucket, COUNT(CASE WHEN account_type = 'SAVINGS' THEN 1 END) AS savings_count, COUNT(CASE WHEN account_type = 'CHECKING' THEN 1 END) AS checking_count, MIN(balance) AS min_balance FROM accounts WHERE status NOT IN ('OPEN', 'CLOSED', 'FROZEN') GROUP BY balance_bucket HAVING min_balance < 58000
